import type { Request, RequestHandler, Response, Router } from 'express';
import type { RouteParameters } from 'express-serve-static-core';
import { isLoopbackAddress } from '../utils/loopback';
import type { RuntimeAdmission } from '../services/RuntimeAdmission';

export const withRuntimeAdmission =
  <Params = Record<string, string>>({
    admission,
    handler,
    isGeneration = false,
  }: {
    admission: RuntimeAdmission;
    handler: (req: Request<Params>, res: Response) => unknown;
    isGeneration?: boolean;
  }): RequestHandler<Params> =>
  async (req, res, next) => {
    if (!isLoopbackAddress(req.socket.remoteAddress)) {
      res
        .status(403)
        .json({
          errorCode: 'RUNTIME_VALIDATION_FAILED',
          message:
            'Variant session routes are only accepted from loopback clients.',
        });
      return;
    }
    const release = admission.enter({
      isGeneration,
      clientVersion: req.header('X-Rivet-Client-Version'),
    });
    if (typeof release !== 'function') {
      res.status(409).json(release);
      return;
    }
    try {
      await handler(req, res);
    } catch (error) {
      next(error);
    } finally {
      release();
    }
  };

export const createRuntimePost =
  ({ router, admission }: { router: Router; admission: RuntimeAdmission }) =>
  <Route extends string>(
    route: Route,
    handler: (req: Request<RouteParameters<Route>>, res: Response) => unknown,
  ): void => {
    router.post(
      route,
      withRuntimeAdmission({
        admission,
        handler,
        isGeneration: route === '/variants/inline',
      }),
    );
  };
